const input=$json.body??$json;
const decision=String(input.negotiation_decision??input.status??'').toLowerCase();
const amount=Number(input.counteroffer_amount??0);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao??0);
const hasMao=mao>0;
const within=hasMao&&amount>0&&amount<=mao;
const near=hasMao&&amount>mao&&amount<=mao*1.10;
const above=hasMao&&amount>mao*1.10;
const dnc=input.dnc===true||decision==='blocked_dnc';
let outcome='needs_review',next='WF-126',reason='negotiation state requires review';
if(dnc){outcome='blocked_dnc';next='WF-126';reason='DNC/contact restriction';}
else if(decision==='contract_ready'||decision==='accepted'){outcome='contract_decision_ready';next='WF-320';reason='seller acceptance is within protected MAO';}
else if(decision==='counteroffer_within_mao'||(decision==='counteroffer'&&within)){outcome='accept_counteroffer';next='WF-320';reason='counteroffer is within dynamic MAO';}
else if(decision==='counteroffer_near_mao'||near){outcome='revised_offer';next='WF-320';reason='counteroffer is near but above dynamic MAO; controlled revision required';}
else if(decision==='counteroffer_above_mao'||above){outcome='walk_away_or_reengage';next='WF-320';reason='counteroffer exceeds protected negotiation band';}
else if(decision==='clarification_response'||decision==='question'){outcome='clarification_response';next='WF-320';reason='seller question requires response before price decision';}
else if(decision==='reengage'||decision==='rejected'||decision==='timeout_followup'){outcome='reengage';next='WF-320';reason='seller is not currently ready to contract';}
return [{json:{...input,workflow_id:'WF-319',workflow_name:'Negotiation Decision → Revised Offer / Contract Decision Controller',outcome,reason,dynamic_mao:mao,counteroffer_amount:amount||null,mao_relationship:amount===0?'unknown':above?'above_110_percent_mao':near?'near_mao':'within_mao',next_workflow:next,human_review_required:['revised_offer','walk_away_or_reengage','needs_review'].includes(outcome),guardrails:{dynamic_mao_protected:hasMao,offer_ceiling:mao||null},crm_activity:{activity_type:'negotiation_outcome',deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,status:outcome,counteroffer_amount:amount||null,reason}}}];
